describe('Form Auto-Save Draft Feature', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should auto-save form as draft every 30 seconds on user interaction', () => {
    // Intercept the API call to save the form
    cy.intercept('POST', '/api/form/save').as('saveForm');

    // Fill in the form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Verify initial state
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');

    // Wait for the first auto-save interval
    cy.wait(30000);

    // Verify the form was saved as a draft
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');
    cy.get('[data-testid="save-button"]').should('be.disabled');

    // Intercept the second auto-save
    cy.intercept('POST', '/api/form/save').as('saveForm2');

    // Wait for the second auto-save interval
    cy.wait(30000);

    // Verify the form was saved again as a draft
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');
    cy.get('[data-testid="save-button"]').should('be.disabled');

    // Verify the API was called twice
    cy.get('@saveForm').then((interception) => {
      expect(interception.request.body).to.include('name');
      expect(interception.request.body).to.include('email');
      expect(interception.request.body).to.include('message');
    });

    // Verify the form is still in draft state
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');
  });

  it('should not auto-save when form is empty or user cancels', () => {
    // Fill in the form fields
    cy.get('[data-testid="name-input"]').type('');
    cy.get('[data-testid="email-input"]').type('');
    cy.get('[data-testid="message-textarea"]').type('');

    // Verify initial state
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');

    // Wait for the first auto-save interval
    cy.wait(30000);

    // Verify the form was not saved (empty fields)
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');
    cy.get('[data-testid="save-button"]').should('be.disabled');

    // Verify the API was not called
    cy.get('@saveForm').should('not.exist');

    // Fill in the form with valid data
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a valid message');

    // Wait for the second auto-save interval
    cy.wait(30000);

    // Verify the form was saved as a draft
    cy.get('[data-testid="form-status"]').should('contain', 'Draft');
    cy.get('[data-testid="save-button"]').should('be.disabled');

    // Verify the API was called
    cy.get('@saveForm2').should('have.length', 1);
  });
});
